def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def digit_sum(n):
        # Calculate sum of digits for positive numbers
        if n >= 0:
            return sum(int(digit) for digit in str(n))
        # For negative numbers, sum absolute digits and add the negative sign
        else:
            return -1 * n - sum(int(digit) for digit in str(abs(n)))

    return sum(1 for num in arr if digit_sum(num) > 0)
